import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{o as t,c as r,a}from"./app-5b3d07bc.js";const n={},i=a(`<h1 id="agent评测-trajectory-aware-evaluation-轨迹感知评测" tabindex="-1"><a class="header-anchor" href="#agent评测-trajectory-aware-evaluation-轨迹感知评测" aria-hidden="true">#</a> Agent评测 - Trajectory-Aware Evaluation 轨迹感知评测</h1><h2 id="面试题-如何做agent评测" tabindex="-1"><a class="header-anchor" href="#面试题-如何做agent评测" aria-hidden="true">#</a> 面试题：如何做Agent评测？</h2><blockquote><p>这是一道综合性面试题，考察对Agent评测体系的完整理解</p></blockquote><hr><h2 id="一、核心理念-为什么要轨迹感知评测" tabindex="-1"><a class="header-anchor" href="#一、核心理念-为什么要轨迹感知评测" aria-hidden="true">#</a> 一、核心理念：为什么要轨迹感知评测？</h2><p>Agent评测的关键：<strong>不能只看结果输出，还应该关注途中的工具调用/参数内容</strong>。</p><p><strong>轨迹感知评测</strong>（Trajectory-Aware Evaluation）就是不只看Agent生成的答案，还要看Agent每一步的决策。</p><p><strong>原因</strong>：</p><ul><li>Agent可能通过错误路径碰巧得到正确答案</li><li>过程中的幻觉和错误调用会积累</li><li>单步错误率会指数级影响整体成功率（单步99%准确率，90次调用后整体只有40%）</li></ul><hr><h2 id="二、评测什么-五个核心维度" tabindex="-1"><a class="header-anchor" href="#二、评测什么-五个核心维度" aria-hidden="true">#</a> 二、评测什么？五个核心维度</h2><h3 id="_1-任务完成率" tabindex="-1"><a class="header-anchor" href="#_1-任务完成率" aria-hidden="true">#</a> 1. 任务完成率</h3><p><strong>注意</strong>：不能看一次通过率（可能有巧合）</p><p><strong>最佳实践</strong>：</p><ul><li>取3次测试，防止因为模型抽风影响评测准确率</li><li>通过多轮测试统计整体成功率</li><li>达标即可认为版本稳定</li></ul><h3 id="_2-幻觉率-⭐" tabindex="-1"><a class="header-anchor" href="#_2-幻觉率-⭐" aria-hidden="true">#</a> 2. 幻觉率 ⭐</h3><p>幻觉类型要拆开，不同类型修复方向不同。Agent幻觉分为三种：</p><table><thead><tr><th>类型</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><strong>未知工具幻觉</strong></td><td>调用了不存在的工具</td><td>调用 <code>deleteUser()</code> 但工具列表里没有</td></tr><tr><td><strong>影子调用</strong></td><td>调用了名字相似的错误工具</td><td>需要 <code>getUserInfo</code> 却调用了 <code>getUserList</code></td></tr><tr><td><strong>参数幻觉</strong></td><td>工具选对了，但参数是编造的</td><td>工具需要userId，用户没给，模型自己编一个</td></tr></tbody></table><h3 id="_3-工具调用准确率" tabindex="-1"><a class="header-anchor" href="#_3-工具调用准确率" aria-hidden="true">#</a> 3. 工具调用准确率</h3><p>考察三个方面：</p><ul><li>工具调对了吗？</li><li>参数填对了吗？</li><li>调用顺序正确吗？</li></ul><p><strong>为什么重要</strong>：Agent完成一个任务平均要调用90次工具</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>单步准确率 99% 
→ 90次调用后：99%^90 ≈ 40%
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-错误恢复率" tabindex="-1"><a class="header-anchor" href="#_4-错误恢复率" aria-hidden="true">#</a> 4. 错误恢复率</h3><p>Agent调用工具失败后的策略：</p><ul><li>直接原地重试？</li><li>更换参数后再试？</li></ul><h3 id="_5-成本延迟" tabindex="-1"><a class="header-anchor" href="#_5-成本延迟" aria-hidden="true">#</a> 5. 成本延迟</h3><ul><li>Token花了多少</li><li>每次任务平均多少钱</li><li>成功案例花了多少</li><li>失败案例花了多少</li></ul><hr><h2 id="三、怎么测-离线评测-在线评测" tabindex="-1"><a class="header-anchor" href="#三、怎么测-离线评测-在线评测" aria-hidden="true">#</a> 三、怎么测？离线评测 + 在线评测</h2><h3 id="离线评测-ci-pipeline" tabindex="-1"><a class="header-anchor" href="#离线评测-ci-pipeline" aria-hidden="true">#</a> 离线评测（CI Pipeline）</h3><p><strong>环境</strong>：跑在CI Pipeline中</p><p><strong>准备</strong>：</p><ul><li>维护 <strong>50-100个 golden tasks</strong>（来自线上真实用户数据，最具代表性）</li><li>每次改工具/切模型/修改Prompt，自动跑一遍这些tasks</li></ul><p><strong>阈值卡控</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>任务完成率下降 2%+        → 打回
幻觉率有上升              → 打回
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>⚠️ 关键原则：幻觉率零容忍</strong></p><p>幻觉率不能做trade off（不可作为权衡指标）</p><p>即使任务完成率涨了1%，幻觉率涨了0.5%，仍然不可接受，需要打回</p></blockquote><p><strong>落地示例</strong>：对应到devtools，就是在push流水线中做这个离线评测</p><h3 id="在线评测-生产环境" tabindex="-1"><a class="header-anchor" href="#在线评测-生产环境" aria-hidden="true">#</a> 在线评测（生产环境）</h3><p><strong>背景</strong>：生产环境因成本原因，不能对每条对话都做深度评测</p><p><strong>最佳实践：分层采样</strong></p><table><thead><tr><th>评测类型</th><th>流量占比</th><th>评测项</th></tr></thead><tbody><tr><td>安全敏感评测</td><td><strong>100%</strong></td><td>PII泄漏、越权操作、脱轨输出</td></tr><tr><td>质量评测</td><td><strong>5%</strong></td><td>任务完成度、回答相关性（采样式评分）</td></tr></tbody></table><hr><h2 id="四、如何裁决结果正确性-规则评测-llm-as-judge" tabindex="-1"><a class="header-anchor" href="#四、如何裁决结果正确性-规则评测-llm-as-judge" aria-hidden="true">#</a> 四、如何裁决结果正确性？规则评测 + LLM-as-Judge</h2><h3 id="规则评测-客观任务" tabindex="-1"><a class="header-anchor" href="#规则评测-客观任务" aria-hidden="true">#</a> 规则评测（客观任务）</h3><p><strong>适用场景</strong>：有客观确定答案的任务</p><p><strong>技术方案</strong>：</p><ul><li>正则匹配</li><li>关键词命中</li><li>将评分规则转化为代码逻辑</li></ul><p><strong>核心价值</strong>：<strong>精准零误差，大幅提升筛选效率</strong></p><h3 id="llm-as-judge-主观任务" tabindex="-1"><a class="header-anchor" href="#llm-as-judge-主观任务" aria-hidden="true">#</a> LLM-as-Judge（主观任务）</h3><p><strong>适用场景</strong>：针对主观任务，<strong>没有对错之分，只有好坏之分</strong></p><p><strong>问题</strong>：LLM很贵，很可能都超过了Agent在业务的花费</p><p><strong>解决方案</strong>：使用专门做评测的小模型</p><ul><li>例如：<strong>Galileo Luna-2 3B-8B</strong></li><li>Agent评测准确率可达 <strong>0.88-0.95</strong></li></ul><p><strong>核心价值</strong>：<strong>评分可追溯、可解释，兼顾效率与公正性</strong></p><h3 id="工程实践-callsphere团队" tabindex="-1"><a class="header-anchor" href="#工程实践-callsphere团队" aria-hidden="true">#</a> 工程实践：CallSphere团队</h3><p>维护 <strong>400-1200条 golden tasks</strong>，每次PR改prompt，CI pipeline上跑 <strong>12个评测器</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>40% → 模型两两对比做裁判
30% → 规则做快速卡位
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="五、进阶方法-probe-suite-探针套件" tabindex="-1"><a class="header-anchor" href="#五、进阶方法-probe-suite-探针套件" aria-hidden="true">#</a> 五、进阶方法：Probe Suite 探针套件</h2><p><strong>目的</strong>：不看正确性，而是看<strong>Agent工具使用起来到底有多脆弱</strong></p><h3 id="三种探针陷阱" tabindex="-1"><a class="header-anchor" href="#三种探针陷阱" aria-hidden="true">#</a> 三种探针陷阱</h3><h4 id="_1-诱饵目录" tabindex="-1"><a class="header-anchor" href="#_1-诱饵目录" aria-hidden="true">#</a> 1. 诱饵目录</h4><p>给Agent一个工具列表，但<strong>把任务需要的工具从列表中拿掉</strong>，看Agent做什么：</p><table><thead><tr><th>Agent行为</th><th>评价</th></tr></thead><tbody><tr><td>拒绝执行</td><td>✓ 正确</td></tr><tr><td>找用户要工具</td><td>✓ 正确</td></tr><tr><td>编造一个</td><td>✗ 说明Agent有严重问题</td></tr></tbody></table><h4 id="_2-影子陷阱" tabindex="-1"><a class="header-anchor" href="#_2-影子陷阱" aria-hidden="true">#</a> 2. 影子陷阱</h4><p>把两个名字很像的工具并列，任务需要a，看Agent会不会选择b</p><h4 id="_3-过度承诺陷阱" tabindex="-1"><a class="header-anchor" href="#_3-过度承诺陷阱" aria-hidden="true">#</a> 3. 过度承诺陷阱</h4><p>在system prompt中写一些超出实际范围的描述</p><ul><li>例如：没有改数据库的权限，但prompt中写&quot;可以修改数据库&quot;</li><li>看Agent会不会尝试执行</li></ul><hr><h2 id="六、评测三大难题及解决方案" tabindex="-1"><a class="header-anchor" href="#六、评测三大难题及解决方案" aria-hidden="true">#</a> 六、评测三大难题及解决方案</h2><h3 id="难题一-模型随机性强" tabindex="-1"><a class="header-anchor" href="#难题一-模型随机性强" aria-hidden="true">#</a> 难题一：模型随机性强</h3><p><strong>问题</strong>：难以判断失败是代码问题还是模型随机抽风</p><p><strong>解决方案</strong>：看概率不看单次</p><ul><li>通过多轮测试统计整体成功率</li><li>达标即可认为版本稳定</li></ul><h3 id="难题二-无标准答案" tabindex="-1"><a class="header-anchor" href="#难题二-无标准答案" aria-hidden="true">#</a> 难题二：无标准答案</h3><p><strong>问题</strong>：主观任务人工打分标准不一致，无法客观判断</p><p><strong>解决方案</strong>：分层打分，量化维度</p><table><thead><tr><th>任务类型</th><th>评测方法</th><th>打分维度</th></tr></thead><tbody><tr><td>客观任务</td><td>代码规则</td><td>精准匹配</td></tr><tr><td>主观任务</td><td>大模型评测</td><td>五个维度</td></tr></tbody></table><p><strong>主观任务五个打分维度</strong>：</p><ol><li><strong>合规性</strong> - 是否符合规范和要求</li><li><strong>准确性</strong> - 信息是否准确无误</li><li><strong>完整性</strong> - 是否覆盖所有必要内容</li><li><strong>专业性</strong> - 表达是否专业得体</li><li><strong>流畅度</strong> - 语言是否流畅自然</li></ol><h3 id="难题三-难以定位问题根源" tabindex="-1"><a class="header-anchor" href="#难题三-难以定位问题根源" aria-hidden="true">#</a> 难题三：难以定位问题根源</h3><p><strong>问题</strong>：难以快速定位问题是提示词、工具、上下文还是模型本身问题</p><p><strong>解决方案</strong>：完整追溯过程数据</p><ul><li>回溯每一步推理、调用和决策过程</li><li>精准定位问题根源</li><li><strong>工具推荐：Langfuse</strong></li></ul><hr><h2 id="七、回答框架速记" tabindex="-1"><a class="header-anchor" href="#七、回答框架速记" aria-hidden="true">#</a> 七、回答框架速记</h2><p>面试时按这个框架回答：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>1. 为什么？轨迹感知评测的核心理念
   → 不只看结果，还看过程
   → 错误会累积（99%^90=40%）

2. 测什么？五个维度
   → 完成率（多轮测）
   → 幻觉率（三类，零容忍）⭐
   → 准确率（工具/参数/顺序）
   → 恢复率（失败策略）
   → 成本（Token延迟）

3. 怎么测？离线+在线
   → 离线：CI Pipeline + 50-100 golden tasks
   → 在线：分层采样（100%安全 + 5%质量）

4. 如何裁决？规则+LLM
   → 客观任务：规则评测（零误差）
   → 主观任务：LLM-as-Judge（小模型）

5. 进阶方法？Probe Suite
   → 诱饵目录、影子陷阱、过度承诺

6. 常见难题？三大难题
   → 随机性 → 多轮测概率
   → 无标准 → 分层打分（五维度）
   → 难定位 → 追溯过程（Langfuse）
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="关键记忆点" tabindex="-1"><a class="header-anchor" href="#关键记忆点" aria-hidden="true">#</a> 关键记忆点</h2><ul><li><strong>幻觉率零容忍</strong>：不能用任务完成率提升来换幻觉率上升</li><li><strong>99%^90=40%</strong>：单步准确率的重要性</li><li><strong>分层采样</strong>：100%安全评测 + 5%质量评测</li><li><strong>40%+30%</strong>：CallSphere的评测器配比（模型40% + 规则30%）</li><li><strong>五维度打分</strong>：合规性、准确性、完整性、专业性、流畅度</li></ul>`,93),d=[i];function s(l,o){return t(),r("div",null,d)}const c=e(n,[["render",s],["__file","trajectory_aware_evaluation.html.vue"]]);export{c as default};
